 function shopUI(kind){const list=GOODS.filter(x=>kind==='charms'?GOODS.indexOf(x)>3:GOODS.indexOf(x)<4);open(kind==='charms'?'授與所・選一份祝福':'參道茶食・白狐小舖',money()+'<p class="muted">款式為本作原創示意，並非官方商品複製。食物購買後可手持並享用。</p><div class="goods-grid">'+list.map(x=>'<article><div class="product-preview"><img src="'+art.thumbnail(x)+'" alt="'+x.name+'的立體款式"></div><h3>'+x.name+'</h3><p>'+x.desc+'</p><button class="journey-btn" data-buy="'+x.id+'">'+(kind==='charms'?'授與':'購買')+' · '+x.price+' 円</button></article>').join('')+'</div>');body.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const x=GOODS.find(x=>x.id===b.dataset.buy);if(spend(x.price)){saved.bag[x.id]=(saved.bag[x.id]||0)+1;equip(x.id);shopUI(kind);toast('已取得 '+x.name+'，可在隨身袋查看。');}});}
 function inventory(){open('隨身袋與旅費',money()+'<p>食品可拿在手上享用；面具與御守可配戴，留在旅行照片裡。</p>');for(const x of GOODS)if(saved.bag[x.id]>0){const row=document.createElement('article');row.className='bag-row';row.innerHTML='<strong>'+x.name+' × '+saved.bag[x.id]+'</strong>';body.append(row);button('手持／配戴',()=>{equip(x.id);toast('已配戴 '+x.name);},row);if(['sushi','senbei','matcha'].includes(x.id))button(x.id==='matcha'?'喝抹茶':'享用',()=>{saved.bag[x.id]--;equip(x.id);startAction('eat',4,()=>{equip(null);toast(x.id==='matcha'?'抹茶的回甘，留在山風裡。':'慢慢享用，收好包裝再繼續散步。');});close();save();},row);}button('收起手持物',()=>{equip(null);snacks.choose('none');});button('補領旅費 + 3,000 円',()=>{saved.coins+=3000;save();inventory();});}
 function fortuneUI(){if(saved.fortune){showFortune();return;}open('御神籤・搖筒問心',money()+'<p>先靜心想一件事，再搖動籤筒抽取籤紙。每支籤都包含詩句、解意與八項運勢。</p><p class="muted">原創籤詩，模擬傳統籤紙格式；不代表大社真實籤文或真實預測。</p>');button('搖筒抽籤 · 100 円',()=>{if(!spend(100))return;close();startAction('draw',2.8,()=>{const n=new Uint32Array(1);crypto.getRandomValues(n);saved.fortune={index:n[0]%FORTUNES.length,number:1+n[0]%99};save();showFortune();});});}
 function showFortune(){const f=saved.fortune;if(!f)return fortuneUI();const a=FORTUNES[f.index];open('展讀御神籤','<article class="fortune-paper"><small>稻荷・星旅　原創御神籤</small><p>第 '+f.number+' 番</p><h3>'+a[0]+'</h3><div class="fortune-poem">'+a[1].replace(/[，。]/g,'<br>')+'</div><p>'+a[2]+'</p><dl>'+labels.map((l,i)=>'<div><dt>'+l+'</dt><dd>'+a[i+3]+'</dd></div>').join('')+'</dl></article><p class="muted">可以收藏，也可以到結籤所結下心事；凶籤不預示現實結果。</p>');button('收好籤紙',()=>{close();toast('籤紙已存入參拜手帖。');});button('到結籤所',()=>{close();travel('tie');});}
 function stopSound(){try{waterSound?.stop();}catch{}waterSound=null;for(const o of tones){try{o.stop();}catch{}}tones.length=0;}
 function ritualSound(type,duration){try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();if(type==='wash'||type==='waterfall'){const buffer=audio.createBuffer(1,audio.sampleRate*2,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.18;const src=audio.createBufferSource(),filter=audio.createBiquadFilter(),gain=audio.createGain();src.buffer=buffer;src.loop=true;filter.type='lowpass';filter.frequency.value=type==='wash'?2200:900;gain.gain.value=.22;src.connect(filter).connect(gain).connect(audio.destination);src.start();src.stop(audio.currentTime+duration);waterSound=src;}if(type==='kagura')for(let i=0;i<8;i++){const o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*2.5;o.type='sine';o.frequency.value=[587,659,784,880][i%4];g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.035,t+.15);g.gain.exponentialRampToValueAtTime(.0001,t+2.2);o.connect(g).connect(audio.destination);o.start(t);o.stop(t+2.3);tones.push(o);}}catch{}}
 function startAction(type,duration,done){if(action)return false;resetInput();ritualSound(type,duration);action={type,duration,left:duration,done};stats.active=type;const id={wash:'wash',draw:'fortune',stone:'stone',tie:'tie',kagura:'kagura',waterfall:'waterfall'}[type];stats.focus=type==='pray'?{id:'pray',x:ritual.site.position[0],y:ritual.site.floor+.9,z:ritual.site.position[2],angle:ritual.site.angle}:sites.find(s=>s.id===id)||null;close();return true;}
 const hands=new THREE.Group();player.add(hands);for(const side of [-1,1])mesh(hands,sphere,mat('#e9c74f'),side*.35,.85,.35,.09,.09,.09);hands.visible=false;const droplets=new THREE.Group();wash.group.add(droplets);for(let i=0;i<16;i++)mesh(droplets,sphere,mat('#a3dbe2'),Math.sin(i*2)*.25,1+i*.02,.3,.015,.05,.015);droplets.visible=false;
