 const actionNames={wash:['舀水・淨左手','淨右手','以掌心承水漱口','淨左手・沖洗杓柄'],pray:['投下賽錢','搖鈴・二鞠躬','二拍手・靜心祈願','一鞠躬'],draw:['靜心','輕搖籤筒','取出籤棒','展開籤紙'],stone:['先許下心願','估量石頭重量','雙手慢慢舉石','感受輕與重'],tie:['摺好籤紙','輕繞橫繩','將籤紙繫好','把心事交給山風'],eat:['慢慢享用','感受香氣','歇一歇','收好包裝'],waterfall:['靜心合掌','聽水聲','緩緩呼吸','感謝與回禮'],kagura:['奉納心意','鈴聲起・舞袖展','祈禱・靜觀','感謝與回禮']};
 function perform(id){const s=sites.find(x=>x.id===id);if(!s)return;stats.previewSite=s;const d=Math.hypot(player.position.x-s.x,player.position.z-s.z);if(d>s.range+1){toast('請先走近 '+s.name);return;}if(id==='shop'||id==='charms')return shopUI(id);if(id==='fortune')return fortuneUI();if(id==='wash'){open(s.name,'<p>依序淨左手、右手，以左掌承水漱口，再淨左手與杓柄。遊戲以文字與水流動畫呈現。</p>');button('開始淨手',()=>startAction('wash',8,()=>{saved.washed=true;save();toast('手水完成，帶著清淨的心前往參拜。');}));}else if(id==='tie'){if(!saved.fortune){toast('先抽一支籤，再帶籤紙到這裡。');return;}open(s.name,'<p>把籤紙繫在指定的結籤繩上，不綁在樹枝或建築。</p>');button('結籤・放下心事',()=>startAction('tie',4,()=>{saved.fortune=null;saved.tied++;save();tiedDisplay();toast('籤紙已繫上，願你安心繼續前行。');}));}else if(id==='stone'){open(s.name,'<p>先在心中許願，想像石頭的重量，再雙手慢慢舉起。比預想輕，象徵願望可期；較重，提醒繼續努力。</p><label>寫下心願（僅保留在此畫面）<input id="stoneWish" maxlength="100" placeholder="願家人平安…"></label>');button('許願・舉起重輕石',()=>startAction('stone',6,()=>{const n=new Uint32Array(1);crypto.getRandomValues(n);open('重輕石・心的回答','<p class="stone-answer">'+(n[0]%2?'比預想中輕，願你把握機緣。':'比預想中重，願你積蓄力量，慢慢實踐。')+'</p><p>這是遊戲模擬，不是對現實願望的預言。</p>');}));}else if(id==='waterfall'){open(s.name,'<p>山林之瀧為原創虛構場景，採合掌、流水與呼吸引導的虛擬修行。非實地瀧場位置或入場安排。</p>');button('開始 15 秒靜心修行',()=>startAction('waterfall',15,()=>{saved.seen.push('waterfall');save();toast('水聲漸遠，把安定帶回旅程。');}));}else if(id==='kagura'){open(s.name,money()+'<p>選擇願意，奉納遊戲內心意，觀賞原創巫女舞祈福演出。演出姿勢與服飾為遊戲化創作，非官方儀軌或預約。</p><label>祈願內容<select id="prayerIntent"><option>家內安全</option><option>商賣繁昌</option><option>身體健全</option><option>學業成就</option><option>心願成就</option><option>神恩感謝</option></select></label>');button('奉納御神樂 · 300 円',()=>{const intent=body.querySelector('select').value;if(spend(300))startAction('kagura',24,()=>{saved.prayers++;save();toast('御神樂奉納完成・'+intent);});});}else if(id.startsWith('art')){open(s.name,'<p>以稻穗、狐與星光為靈感的原創攝影藝術裝置。靠近選擇角度，把小星星與旅途中收集的御守一起拍進照片。</p>');button('進入攝影模式',()=>{close();togglePhoto();});}}
 async function loadMiko(){if(miko||mikoPending)return;mikoPending=true;try{const gltf=await queueAsset('miko',()=>new GLTFLoader().loadAsync(asset('v3.1/mei-vendor.glb')));const model=gltf.scene;model.updateMatrixWorld(true);const b=new THREE.Box3().setFromObject(model),size=b.getSize(new THREE.Vector3()),center=b.getCenter(new THREE.Vector3()),scale=1.7/size.y;model.scale.setScalar(scale);model.position.set(-center.x*scale,-b.min.y*scale,-center.z*scale);const head=new THREE.Group();model.updateMatrixWorld(true);model.traverse(o=>{if(!o.isMesh||/elegantsuit|shoes/.test(o.material?.name||''))return;const geo=o.geometry.clone();for(const name of ['position','normal','uv']){const a=geo.attributes[name];if(!a)continue;const data=new Float32Array(a.count*a.itemSize);for(let i=0;i<a.count;i++)for(let k=0;k<a.itemSize;k++)data[i*a.itemSize+k]=a.getComponent(i,k);geo.setAttribute(name,new THREE.BufferAttribute(data,a.itemSize));}if(o.isSkinnedMesh){o.skeleton.update();const a=geo.attributes.position,v=new THREE.Vector3();for(let i=0;i<a.count;i++){v.fromBufferAttribute(a,i);o.applyBoneTransform(i,v);a.setXYZ(i,v.x,v.y,v.z);}}geo.applyMatrix4(o.matrixWorld);geo.translate(0,0,0);const pos=geo.attributes.position,idx=geo.index,out=[];for(let i=0;i<(idx?idx.count:pos.count);i+=3){const ids=[0,1,2].map(k=>idx?idx.getX(i+k):i+k);if(ids.every(j=>pos.getY(j)>1.3))out.push(...ids);}geo.setIndex(out);geo.computeVertexNormals();if(out.length){const m=o.material.clone();if(/hair/.test(m.name))m.color.set('#3a2c25');head.add(new THREE.Mesh(geo,m));}});const root=new THREE.Group();root.add(head);const costume=art.mikoCostume(root);const fan=costume.fan;root.position.set(0,.24,0);kagura.group.add(root);stats.mikoHeadParts=head.children.length;miko={root,fan,model,arms:costume.arms};}catch(e){stats.mikoError=e.message;}finally{mikoPending=false;}}
 function safeArrival(s){for(let r=2.8;r<12;r+=.6)for(let i=0;i<24;i++){const a=i/24*Math.PI*2+Math.PI/2,x=s.x+Math.cos(a)*r,z=s.z+Math.sin(a)*r,y=world.walkHeight(x,z);if(Number.isFinite(y)&&!world.physics.collides(x,y,z))return{x,y,z};}return world.safePlace(s.place);}
 function travel(id){const s=sites.find(s=>s.id===id);if(!s)return;close();goPlace(s.place);const p=safeArrival(s);player.position.set(p.x,p.y,p.z);window.inari.setView(Math.atan2(p.x-s.x,p.z-s.z),.16,6);stats.visits++;toast('已來到 '+s.name);}
